use crate::{storage::Database,power_manager};use serde_json::{json,Value};use rusqlite::params;use tauri::{Manager,AppHandle};use std::sync::atomic::{AtomicBool,Ordering};
#[derive(Default)]pub struct GameControl(pub AtomicBool);
pub const BALANCED:&str="381b4222-f694-41f0-9685-ff5bb260df2e";pub const GAMING:&str="8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c";
pub fn target(mode:&str)->Result<Option<&'static str>,String>{match mode{"Safe"=>Ok(None),"Balanced"=>Ok(Some(BALANCED)),"Gaming"=>Ok(Some(GAMING)),_=>Err("Perfil não suportado".into())}}
pub fn preview(mode:&str)->Result<Value,String>{let target=target(mode)?;if target.is_none(){return Ok(json!({"mode":mode,"previous":crate::power_manager::active().ok(),"next":null,"supported":true,"reason":"Lançamento sem alterações de energia","risk":"Sem alterações temporárias"}));}let active=power_manager::active()?;let plans=power_manager::plans()?;let installed=target.is_some_and(|id|plans.as_array().is_some_and(|p|p.iter().any(|v|v["id"]==id)));Ok(json!({"mode":mode,"previous":active,"next":if installed{target.map(str::to_string)}else{None},"supported":target.is_none()||installed,"reason":if target.is_some()&&!installed{"O plano pretendido não está instalado; não será criado ou simulado"}else{"Sem alterações de segurança ou encerramento de aplicações"},"risk":if mode=="Gaming"{"Pode aumentar consumo, ruído e temperatura; ganhos de FPS não garantidos"}else{"Alteração temporária reversível"}}))}
pub fn launch(app:AppHandle,id:i64,mode:&str,expected:&str)->Result<Value,String>{
 let control=app.state::<GameControl>();if control.0.compare_exchange(false,true,Ordering::SeqCst,Ordering::SeqCst).is_err(){return Err("Já existe uma sessão gerida. Aguarde que termine ou use o lançamento simples.".into())}
 let result=(||{let runtime=app.state::<crate::Runtime>();let _guard=runtime.operation.lock().map_err(|e|e.to_string())?;let db=app.state::<Database>();let(name,path):(String,String)=db.0.lock().map_err(|e|e.to_string())?.query_row("SELECT name,executable FROM profiles WHERE id=?1",[id],|r|Ok((r.get(0)?,r.get(1)?))).map_err(|e|e.to_string())?;let path=crate::game_manager::validate(&path)?;let plan=preview(mode)?;if mode!="Safe"&&plan["previous"]!=expected{return Err("O plano de energia mudou desde a pré-visualização".into())}if plan["supported"]!=true{return Err(plan["reason"].as_str().unwrap_or("Perfil não suportado").into())}let change=if let Some(next)=plan["next"].as_str(){power_manager::apply(&db,next,expected)?["id"].as_i64()}else{None};
 let spawned=std::process::Command::new(&path).current_dir(path.parent().ok_or("Pasta inválida")?).spawn();let mut child=match spawned{Ok(child)=>child,Err(e)=>{if let Some(change)=change{power_manager::restore(&db,change).map_err(|restore|format!("O jogo não iniciou ({e}); restauro pendente: {restore}"))?;}return Err(e.to_string())}};
 let pid=child.id();let saved=(||->Result<i64,String>{let conn=db.0.lock().map_err(|e|e.to_string())?;conn.execute("INSERT INTO game_sessions(profile_id,game_name,pid,mode,power_change,status) VALUES(?1,?2,?3,?4,?5,'running')",params![id,name,pid,mode,change]).map_err(|e|e.to_string())?;Ok(conn.last_insert_rowid())})();let session=match saved{Ok(id)=>id,Err(e)=>{if let Some(change)=change{let _=power_manager::restore(&db,change);}return Err(format!("O jogo iniciou, mas a sessão não foi guardada: {e}"))}};let audit_warning=db.log("game.session.start",&json!({"id":session,"pid":pid,"power_change":change}).to_string()).err();
 let monitor_app=app.clone();std::thread::spawn(move||{let waited=child.wait().map_err(|e|e.to_string());let runtime=monitor_app.state::<crate::Runtime>();let outcome=runtime.operation.lock().map_err(|e|e.to_string()).and_then(|_guard|{let db=monitor_app.state::<Database>();if let Some(change)=change{power_manager::restore(&db,change)?;}Ok(())});let db=monitor_app.state::<Database>();let error=outcome.err().or_else(||waited.err());if let Ok(conn)=db.0.lock(){let _=conn.execute("UPDATE game_sessions SET status=?1,ended_at=CURRENT_TIMESTAMP,error=?2 WHERE id=?3",params![if error.is_some(){"restore_pending"}else{"completed"},error,session]);}let _=db.log("game.session.end",&json!({"id":session,"error":error}).to_string());monitor_app.state::<GameControl>().0.store(false,Ordering::SeqCst);});Ok(json!({"id":session,"pid":pid,"power_change":change,"audit_warning":audit_warning}))})();if result.is_err(){control.0.store(false,Ordering::SeqCst);}result
}
#[cfg(test)]mod tests{use super::*;#[test]fn profiles_never_include_unknown_actions(){assert_eq!(target("Safe").unwrap(),None);assert_eq!(target("Balanced").unwrap(),Some(BALANCED));assert_eq!(target("Gaming").unwrap(),Some(GAMING));assert!(target("Unlimited").is_err());}}
